// get listening attr
var listening = node.listening();

// stop listening for events, remove node and all its children from hit graph
node.listening(false);

// listen to events according to the parent
node.listening(true);

// get preventDefault
var shouldPrevent = shape.preventDefault();

// set preventDefault
